import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 기존 회계시스템 연계 호출 수단이 입력에 없어, 전표(journal_voucher)는 이 트랜잭션에서 직접 만든다.
// 가정: 전표일자는 처리 당일, 원천 구분은 PAYROLL, 상태는 승인, 전표번호는 'PR-' + 10자리 전표 ID.
const VOUCHER_SOURCE_TYPE = 'PAYROLL';
const VOUCHER_STATUS = 'Approved';
const VOUCHER_STATUS_KO = '승인';
const VOUCHER_NO_PREFIX = 'PR-';

@Controller('api/v1')
export class FnSfr02105Controller {
  @Post('/paydays/:paydayId/process-voucher')
  @HttpCode(200)
  async processPayrollVoucher(@Req() req: Request) {
    const user = currentUser(req);
    user.require('급여 담당자');
    const paydayId = req.params['paydayId'];
    if (!/^[0-9]+$/.test(paydayId ?? '')) {
      throw new ApiError(400, 'VALIDATION_FAILED', '지급일 ID가 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT status AS "status", journal_voucher_id AS "journalVoucherId" FROM payday WHERE payday_id = CAST(:paydayId AS bigint) FOR UPDATE',
        { paydayId },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'PAYDAY_NOT_FOUND', '지급일을 찾을 수 없습니다.');
      }
      const current = found[0];
      if (current.status === '전표처리' || current.journalVoucherId !== null) {
        throw new ApiError(409, 'VOUCHER_ALREADY_PROCESSED', '이미 전표처리된 지급일입니다.');
      }
      if (current.status !== '마감') {
        throw new ApiError(409, 'PAYDAY_NOT_CLOSED', '마감되지 않은 급여는 전표처리할 수 없습니다.');
      }
      const created = await db.query(
        'INSERT INTO journal_voucher (voucher_date, source_type, status, created_at, updated_at) ' +
          'VALUES (CURRENT_DATE, :sourceType, :status, now(), now()) ' +
          'RETURNING journal_voucher_id AS "journalVoucherId"',
        { sourceType: VOUCHER_SOURCE_TYPE, status: VOUCHER_STATUS_KO },
      );
      const voucherId = created[0].journalVoucherId;
      const numbered = await db.query(
        'UPDATE journal_voucher SET voucher_no = :prefix || lpad(CAST(journal_voucher_id AS text), 10, \'0\'), updated_at = now() ' +
          'WHERE journal_voucher_id = CAST(:voucherId AS bigint) RETURNING voucher_no AS "voucherNo"',
        { prefix: VOUCHER_NO_PREFIX, voucherId },
      );
      const updated = await db.query(
        'UPDATE payday SET status = :status, journal_voucher_id = CAST(:voucherId AS bigint), ' +
          'voucher_processed_at = now(), updated_at = now() ' +
          'WHERE payday_id = CAST(:paydayId AS bigint) ' +
          'RETURNING payday_id AS "paydayId", status AS "status", journal_voucher_id AS "journalVoucherId"',
        { status: '전표처리', voucherId, paydayId },
      );
      return {
        paydayId: updated[0].paydayId,
        status: updated[0].status,
        journalVoucherId: updated[0].journalVoucherId,
        voucherNo: numbered[0].voucherNo,
      };
    });
  }
}

