import { useState } from 'react';
import {
  Band,
  Badge,
  DataTable,
  Drawer,
  Field,
  Form,
  LookupSelect,
  Pairs,
  RefName,
  Tiles,
  call,
} from '../kit';
import type { PageProps, Row } from '../kit';

export default function FnSfr02105Page({ role, notify }: PageProps) {
  const [results, setResults] = useState<Row[]>([]);
  const [opened, setOpened] = useState(false);
  const [detail, setDetail] = useState<Row | undefined>(undefined);
  const [paydayId, setPaydayId] = useState<number | string>('');

  async function submit() {
    if (paydayId === '' || paydayId === undefined) {
      throw new Error('전표처리할 급여 지급일을 선택하세요.');
    }
    const result = await call('POST', '/paydays/' + paydayId + '/process-voucher', role, {});
    setResults((prev) => [result, ...prev.filter((r) => r.paydayId !== result.paydayId)]);
    notify('급여 전표처리를 했습니다.');
    setOpened(false);
    setPaydayId('');
  }

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>처리 현황</h2>
        <Tiles items={[['이번 접속 전표처리', results.length + '건']]} />
      </section>
      <section className="box span-12">
        <h2>전표처리 결과</h2>
        <Band total={results.length}>
          <button type="button" onClick={() => setOpened(true)}>
            급여 전표처리
          </button>
        </Band>
        <DataTable
          columns={[
            {
              key: 'paydayId',
              label: '급여 지급일',
              render: (r) => <RefName table="payday" role={role} value={r.paydayId} />,
            },
            { key: 'status', label: '처리 상태', render: (r) => <Badge value={r.status} /> },
            { key: 'voucherNo', label: '전표번호' },
            {
              key: 'journalVoucherId',
              label: '전표',
              render: (r) => (
                <RefName table="journal_voucher" role={role} value={r.journalVoucherId} />
              ),
            },
          ]}
          rows={results}
          onRowClick={(r) => setDetail(r)}
          empty="처리한 전표가 없습니다."
        />
      </section>
      {opened && (
        <Drawer title="급여 전표처리" onClose={() => setOpened(false)}>
          <Form onSubmit={submit} submit="전표처리 요청">
            <Field label="급여 지급일" required wide>
              <LookupSelect
                table="payday"
                role={role}
                value={paydayId}
                onChange={setPaydayId}
                placeholder="마감된 지급일 선택"
              />
            </Field>
          </Form>
        </Drawer>
      )}
      {detail && (
        <Drawer title="전표 상세" onClose={() => setDetail(undefined)}>
          <Pairs
            items={[
              ['급여 지급일', <RefName table="payday" role={role} value={detail.paydayId} />],
              ['처리 상태', <Badge value={detail.status} />],
              ['전표번호', String(detail.voucherNo ?? '')],
              [
                '전표',
                <RefName table="journal_voucher" role={role} value={detail.journalVoucherId} />,
              ],
            ]}
          />
        </Drawer>
      )}
    </div>
  );
}
